public async Task<string> AnswerAsync(
    string question,
    CancellationToken ct = default)
{
    var queryVector = await _embeddingGenerator.GenerateAsync(
        new[] { question }, ct);

    var candidates = await _vectorStore.SearchAsync(
        queryVector[0].Vector, topK: 5, ct);

    var context = string.Join("\n---\n", candidates.Select(c => c.Text));
    var prompt = $"""Answer using only the context below. Cite sources.

Context:
{{context}}

Question:
{{question}}
""";

    var response = await _chatClient.GetResponseAsync(
        new[] { new ChatMessage(ChatRole.User, prompt) }, ct);

    return response.Messages.Last().Text ?? string.Empty;
}
